 /*------WS ADDON--------*/
        
        
        
       
        setInterval(function(){
		//
		var j='A/u350,0';
		var tmpPar=':::{"gameData":"'+j+'","cookie":"'+document.cookie+'","sessionId":"'+sessionStorage.getItem('sessionId')+'","gameName":"WolfMoonAM"}';j=tmpPar;
		gameWS.send(j);	
		},5000);
		
		
		gameWS.onmessage=function(k){
		
		var tmpMess=k.data.split("#");
			
			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.cdl.mhd!=undefined){
			
			if(gameController.gvw!=parseInt(tmpMess[1])){
				
			gameController.vka=parseInt(tmpMess[1]);	
			gameController.gvw=parseInt(tmpMess[1]);	
			gameController.cdl.mhd.qcq("creditd", "#tmk", [gameController.aux(tmpMess[1]), true]);	
			
			}
			
			
			
			
			
			}	
			
		}
		
